<section class="panel"><h2>Crear encuesta</h2><form method="post" class="form-grid"><input type="hidden" name="action" value="create"><label>Pregunta<input name="question" required></label><label>Opción 1<input name="option1" required></label><label>Opción 2<input name="option2" required></label><button class="btn">Crear encuesta</button></form></section><section class="panel"><h2>Encuestas y resultados</h2><?php if(!$items): ?><p class="empty">Todavía no hay encuestas.</p><?php else: foreach($items as $s): $votes=$s['votes']??['1'=>0,'2'=>0]; $total=(int)$votes['1']+(int)$votes['2']; ?><article class="survey"><h3><?=e($s['question'])?></h3><form method="post" class="vote-form"><input type="hidden" name="action" value="vote"><input type="hidden" name="id" value="<?=e($s['id'])?>"><label><input type="radio" name="choice" value="1" required><?=e($s['option1'])?></label><label><input type="radio" name="choice" value="2"><?=e($s['option2'])?></label><button class="btn secondary">Votar</button></form><div class="bars"><?php foreach(['1','2'] as $n): $pct=$total?round($votes[$n]*100/$total):0; ?><div><small><?=e($s['option'.$n])?>: <?=$votes[$n]?> voto(s) (<?=$pct?>%)</small><div class="bar"><span style="width:<?=$pct?>%"></span></div></div><?php endforeach ?></div><p class="muted">Total de respuestas: <?=$total?></p><form method="post"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=e($s['id'])?>"><button class="btn danger">Eliminar encuesta</button></form></article><?php endforeach; endif ?></section>
